import Footer from '@/app/components/Footer';
import FloatingNav from '@/app/components/FloatingNav';
import TLDR from '@/app/components/TLDR';
import { getBlogPost } from '@/lib/blog';
import Script from 'next/script';

// Generate metadata for each blog post
export async function generateMetadata({ params }) {
  const { blogId } = await params;
  const blogPost = getBlogPost(blogId);

  if (!blogPost) {
    return {
      title: 'Blog Post Not Found',
      description: 'The requested blog post could not be found.'
    };
  }

  const canonicalUrl = `https://yogesh.co/${blogPost.slug}`;
  const openGraphImage = `${canonicalUrl}/opengraph-image`;

  return {
    title: blogPost.meta_title,
    description: blogPost.meta_description,
    openGraph: {
      title: blogPost.social_title,
      description: blogPost.meta_description,
      type: 'article',
      url: canonicalUrl,
      publishedTime: blogPost.published_date,
      modifiedTime: blogPost.modified_date,
      images: [
        {
          url: openGraphImage,
          width: 1200,
          height: 630,
          alt: blogPost.title,
        },
      ],
    },
    twitter: {
      card: 'summary_large_image',
      title: blogPost.social_title,
      description: blogPost.meta_description,
      images: [openGraphImage],
    },

    alternates: {
      canonical: canonicalUrl,
    },
  };
}

// Function to format date
const formatDate = (dateString) => {
  const date = new Date(dateString);
  const options = { 
    year: 'numeric', 
    month: 'short', 
    day: 'numeric' 
  };
  return date.toLocaleDateString('en-US', options);
};

export default async function BlogPost({ params }) {
  const { blogId } = await params;
  const blogPost = getBlogPost(blogId);

  if (!blogPost) {
    return (
      <div className="min-h-screen font-[450]">
        <FloatingNav />
        <main className="px-8 pb-8 pt-28 sm:py-12">
          <div className="mx-auto max-w-lg py-16 text-center">
            <h1 className="mb-4 text-2xl font-medium">Blog post not found</h1>
            <p className="text-muted-foreground">The blog post you&apos;re looking for doesn&apos;t exist.</p>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen font-[450]">
      <FloatingNav sections={blogPost.headings} />
      <Script 
        id="structured-data"
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "BlogPosting",
            "headline": blogPost.meta_title,
            "author": {
              "@type": "Person",
              "name": "Yogesh"
            },
            "datePublished": blogPost.published_date,
            "dateModified": blogPost.modified_date,
            "mainEntityOfPage": {
              "@type": "WebPage",
              "@id": `https://yogesh.co/${blogPost.slug}`
            },
            "publisher": {
              "@type": "Organization",
              "name": "Yogesh",
              "logo": {
                "@type": "ImageObject",
                "url": "https://yogesh.co/yogesh.jpg"
              }
            },
            "description": blogPost.meta_description,
            "image": `https://yogesh.co/${blogPost.slug}/opengraph-image`
          })
        }}
      />
      {/* Main Content */}
      <main className="px-8 pb-8 pt-28 sm:py-12">
        <article className="mx-auto max-w-lg">
          <header className="mb-8">
            <div className="mb-4 text-sm text-muted-foreground">
              {formatDate(blogPost.published_date)}
            </div>
            <h1 className="text-2xl font-medium leading-tight">
              {blogPost.title}
            </h1>
          </header>

          {/* Blog Content */}
          <div
            className="max-w-none markdown-content"
            dangerouslySetInnerHTML={{ __html: blogPost.content }}
          />

          {/* TLDR */}
          {blogPost.tldrItems && <TLDR items={blogPost.tldrItems} />}
        </article>
      </main>
      <Footer />
    </div>
  );
}

