import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import Prism from 'prismjs';
import 'prismjs/components/prism-python.js';

const postsDirectory = path.join(process.cwd(), 'content/blog');

// Configure marked options for better HTML output
marked.setOptions({
  breaks: true,
  gfm: true,
});

// Parse TLDR block from content
function parseTLDR(content) {
  const tldrRegex = /:::tldr\n([\s\S]*?)\n:::/;
  const match = content.match(tldrRegex);

  if (!match) {
    return { content, tldrItems: null };
  }

  const tldrContent = match[1];
  const items = tldrContent
    .split('\n')
    .map(line => line.replace(/^\d+\.\s*/, '').trim())
    .filter(line => line.length > 0);

  const contentWithoutTLDR = content.replace(tldrRegex, '');

  return { content: contentWithoutTLDR, tldrItems: items };
}

function getHeadingText(tokens) {
  return tokens
    .map(token => token.tokens ? getHeadingText(token.tokens) : (token.text || ''))
    .join('');
}

function escapeHtml(value) {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function getBlogPost(slug) {
  try {
    const fullPath = path.join(postsDirectory, `${slug}.md`);

    // Check if file exists
    if (!fs.existsSync(fullPath)) {
      return null;
    }

    const fileContents = fs.readFileSync(fullPath, 'utf8');
    const { data, content } = matter(fileContents);

    // Parse TLDR if present
    const { content: contentWithoutTLDR, tldrItems } = parseTLDR(content);

    // Build the table of contents while adding matching IDs to headings.
    const headings = [];
    const usedHeadingIds = new Map();
    const renderer = new marked.Renderer();

    renderer.heading = function ({ depth, tokens }) {
      const headingText = getHeadingText(tokens);
      const baseId = headingText
        .toLowerCase()
        .normalize('NFKD')
        .replace(/[^\p{Letter}\p{Number}]+/gu, '-')
        .replace(/^-+|-+$/g, '') || 'section';
      const duplicateCount = usedHeadingIds.get(baseId) || 0;
      const id = duplicateCount ? `${baseId}-${duplicateCount + 1}` : baseId;

      usedHeadingIds.set(baseId, duplicateCount + 1);

      if (depth >= 2) {
        headings.push({ id, text: headingText, depth });
      }

      return `<h${depth} id="${id}">${this.parser.parseInline(tokens)}</h${depth}>\n`;
    };

    renderer.code = function ({ text, lang }) {
      const requestedLanguage = lang?.trim().split(/\s+/, 1)[0].toLowerCase();
      const language = requestedLanguage === 'py' ? 'python' : requestedLanguage;
      const grammar = language ? Prism.languages[language] : null;
      const code = grammar
        ? Prism.highlight(text, grammar, language)
        : escapeHtml(text);
      const languageClass = grammar ? ` class="language-${language}"` : '';

      return `<pre><code${languageClass}>${code}</code></pre>\n`;
    };

    // Convert markdown to HTML
    const htmlContent = marked(contentWithoutTLDR, { renderer });

    return {
      slug,
      title: data.title,
      meta_title: data.meta_title,
      social_title: data.social_title || data.title,
      meta_description: data.meta_description,
      published_date: data.published_date,
      modified_date: data.modified_date,
      content: htmlContent,
      headings,
      tldrItems
    };
  } catch (error) {
    console.error(`Error reading blog post ${slug}:`, error);
    return null;
  }
}

export function getAllBlogPosts() {
  try {
    // Check if directory exists
    if (!fs.existsSync(postsDirectory)) {
      return [];
    }

    const fileNames = fs.readdirSync(postsDirectory);
    const allPostsData = fileNames
      .filter(fileName => fileName.endsWith('.md'))
      .map(fileName => {
        const slug = fileName.replace(/\.md$/, '');
        const fullPath = path.join(postsDirectory, fileName);
        const fileContents = fs.readFileSync(fullPath, 'utf8');
        const { data } = matter(fileContents);

        return {
          slug,
          title: data.title,
          published_date: data.published_date,
          modified_date: data.modified_date,
          meta_title: data.meta_title,
          social_title: data.social_title || data.title,
          meta_description: data.meta_description,
        };
      })
      .sort((a, b) => {
        if (a.published_date < b.published_date) {
          return 1;
        } else {
          return -1;
        }
      });

    return allPostsData;
  } catch (error) {
    console.error('Error reading blog posts:', error);
    return [];
  }
}

